import sys
from collections import deque

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    k = int(input[index + 1])
    index += 2
    main_courses = set(map(int, input[index:index + k]))
    index += k
    graph = {i: [] for i in range(1, n + 1)}
    in_degree = [0] * (n + 1)
    for i in range(1, n + 1):
        num_prerequisites = int(input[index])
        index += 1
        for _ in range(num_prerequisites):
            prerequisite = int(input[index])
            index += 1
            graph[prerequisite].append(i)
            in_degree[i] += 1

    queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])
    topological_order = []
    while queue:
        node = queue.popleft()
        topological_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) != n:
        print(-1)
        return

    result = []
    visited = set()
    for course in topological_order:
        if course in main_courses and course not in visited:
            result.append(course)
            visited.add(course)
        elif course not in main_courses:
            for dependent in graph[course]:
                if dependent in main_courses and dependent not in visited:
                    result.append(dependent)
                    visited.add(dependent)
        if len(visited) == k:
            break

    if len(result) < k:
        print(-1)
    else:
        print(len(result))
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
